(function(){'use strict';const hasSentry=typeof Sentry !=='undefined';window.addEventListener('error',function(event){console.error('[Global Error]',{message:event.message,filename:event.filename,lineno:event.lineno,colno:event.colno,error:event.error});if(hasSentry){Sentry.captureException(event.error || new Error(event.message));}return false;});window.addEventListener('unhandledrejection',function(event){console.error('[Unhandled Promise Rejection]',event.reason);if(hasSentry){Sentry.captureException(event.reason);}});console.log('[Error Handler] Global error handler initialized');})();